import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"JavaScript开发中的性能优化","description":"最近工作比较清闲，5 月又换了一个工作环境。总结下最近看的有关 JavaScript 性能的知识，并记下来供未来的自己参考。希望自己能不忘初心，继续成长！","frontmatter":{"title":"JavaScript开发中的性能优化","date":"2018-04-25 23:22","comments":true,"archives":2018,"tags":["js","performance"]},"headers":[],"relativePath":"posts/2018-04-25-javascript-performance/index.md","filePath":"posts/2018/2018-04-25-javascript-performance.md"}'),p={name:"posts/2018-04-25-javascript-performance/index.md"};function r(o,s,t,c,i,y){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>最近工作比较清闲，5 月又换了一个工作环境。总结下最近看的有关 JavaScript 性能的知识，并记下来供未来的自己参考。希望自己能不忘初心，继续成长！</p><h2 id="使用-requestanimationframe-来更新动画" tabindex="-1">使用 requestAnimationFrame 来更新动画 <a class="header-anchor" href="#使用-requestanimationframe-来更新动画" aria-label="Permalink to &quot;使用 requestAnimationFrame 来更新动画&quot;">​</a></h2><p>使用<code>requestAnimationFrame</code>把动画渲染交给浏览器，可以保证渲染保持在 60FPS。应该避免使用<code>setTimeout</code>或者<code>setInterval</code>来实现动画，因为计时器和事件队列会消耗更多的资源，还会导致无用的页面重新绘制。</p><h2 id="使用-web-workers-来进行复杂的运算" tabindex="-1">使用 Web Workers 来进行复杂的运算 <a class="header-anchor" href="#使用-web-workers-来进行复杂的运算" aria-label="Permalink to &quot;使用 Web Workers 来进行复杂的运算&quot;">​</a></h2><p>可以把单纯的计算放在 Web Workers 中，这样不影响主页面的渲染和流畅，例如加密和矩阵变换的运算就可以完全放在 Web Workers 中来减少主线程的执行时间，避免浏览器渲染堵塞。</p><h2 id="避免微优化-javascript" tabindex="-1">避免微优化 JavaScript <a class="header-anchor" href="#避免微优化-javascript" aria-label="Permalink to &quot;避免微优化 JavaScript&quot;">​</a></h2><p>举个最简单的例子，我曾经在一本书上看到过一个提升程序效率的例子。大致是这样的：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> array </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> [</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">3</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">...</span><span style="color:#005CC5;">100</span><span style="color:#24292E;">];</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">for</span><span style="color:#24292E;"> (</span><span style="color:#D73A49;">var</span><span style="color:#24292E;"> i </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">; i </span><span style="color:#D73A49;">&lt;</span><span style="color:#24292E;"> array.</span><span style="color:#005CC5;">length</span><span style="color:#24292E;">; i</span><span style="color:#D73A49;">++</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#24292E;">  console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(array[i]);</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这里的<code>array.length</code>获取数组的长度，每次都要计算数组长度会消耗不少时间，优化之后的代码是这样的：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> array </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> [</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">3</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">...</span><span style="color:#005CC5;">100</span><span style="color:#24292E;">];</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> len </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> array.</span><span style="color:#005CC5;">length</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">for</span><span style="color:#24292E;"> (</span><span style="color:#D73A49;">var</span><span style="color:#24292E;"> i </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">; i </span><span style="color:#D73A49;">&lt;</span><span style="color:#24292E;"> len; i</span><span style="color:#D73A49;">++</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#24292E;">  console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(array[i]);</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>通过缓存数组的长度来保证只计算一次。这就是典型的微优化，说实话这段代码我一直在用，直到最近读了其他的书才发现，现在的 JS 解释器早就优化了对数组长度的计算。无论是读取一次还是一万次消耗的时间都没有太大差别。微优化应该是 JS 引擎需要做的事情，我们不应该在实际开发中在这方面耗费过多的时间。</p><h2 id="滑动事件优化" tabindex="-1">滑动事件优化 <a class="header-anchor" href="#滑动事件优化" aria-label="Permalink to &quot;滑动事件优化&quot;">​</a></h2><p>当用户监听滑动事件并执行相关动画操作的时候，记得使用<code>window.requestAnimationFrame</code>来优化动画的执行。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> onScroll</span><span style="color:#24292E;">(</span><span style="color:#E36209;">evt</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#6A737D;">  // Prevent multiple rAF callbacks.</span></span>
<span class="line"><span style="color:#D73A49;">  if</span><span style="color:#24292E;"> (scheduledAnimationFrame) </span><span style="color:#D73A49;">return</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">  scheduledAnimationFrame </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> true</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">  requestAnimationFrame</span><span style="color:#24292E;">(readAndUpdatePage);</span></span>
<span class="line"><span style="color:#24292E;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> readAndUpdatePage</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#6A737D;">  // do something</span></span>
<span class="line"><span style="color:#6F42C1;">  requestAnimationFrame</span><span style="color:#24292E;">(readAndUpdatePage);</span></span>
<span class="line"><span style="color:#24292E;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">window.</span><span style="color:#6F42C1;">addEventListener</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;scroll&#39;</span><span style="color:#24292E;">, onScroll);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>参考：</p><p><a href="https://developers.google.com/web/fundamentals/performance/rendering/debounce-your-input-handlers" target="_blank" rel="noreferrer">Debounce Your Input Handlers</a></p><p><a href="https://developers.google.com/web/fundamentals/performance/rendering/optimize-javascript-execution" target="_blank" rel="noreferrer">Optimize JavaScript Execution</a></p>`,17)])])}const u=a(p,[["render",r]]);export{b as __pageData,u as default};
